class Solution { int height(TreeNode* node){return node?1+max(height(node->left),height(node->right)):0;}void fill(TreeNode* node,int row,int left,int right,vector<vector<string>>& answer){if(!node)return;int middle=(left+right)/2;answer[row][middle]=to_string(node->val);fill(node->left,row+1,left,middle-1,answer);fill(node->right,row+1,middle+1,right,answer);}public:vector<vector<string>> printTree(TreeNode* root){int rows=height(root),columns=(1<<rows)-1;vector<vector<string>> answer(rows,vector<string>(columns));fill(root,0,0,columns-1,answer);return answer;} };
